429	/** Presentation expiry is synchronous; the core independently erases durable data. */
430	export function messageExpired(message: ChatMessage, now: number): boolean {
431	  return message.expiresAtMs != null && message.expiresAtMs <= now;
432	}
433	
434	export function expireConversationMessages(
435	  state: ConversationCacheState,
436	  now: number,
437	): Partial<ConversationCacheState> {
438	  let messages = state.messages;
439	  let reactions = state.reactions;
440	  for (const [key, rows] of Object.entries(state.messages)) {
441	    const expired = new Set(
442	      rows.filter((m) => messageExpired(m, now)).map((m) => m.id),
443	    );
444	    if (!expired.size) continue;
445	    if (messages === state.messages) messages = { ...messages };
446	    messages[key] = rows.filter((m) => !messageExpired(m, now));
447	    if (reactions[key]?.some((r) => expired.has(r.target))) {
448	      if (reactions === state.reactions) reactions = { ...reactions };
449	      reactions[key] = reactions[key].filter((r) => !expired.has(r.target));
450	    }
451	  }
452	  const expiredIntents = Object.keys(state.intents).filter((id) =>
453	    messageExpired(state.intents[id].message, now),
454	  );
455	  let intents = state.intents;
456	  if (expiredIntents.length) {
457	    intents = { ...intents };
458	    for (const id of expiredIntents) delete intents[id];
459	  }
460	  return { messages, reactions, intents };
461	}

